/* Return 1 if cell (col,row) of `level` is solid. */
static int cc_cell_solid(int level, int col, int row) {
    if (level < 0 || level >= CELL_LEVELS) return 1;
    if (col < 0 || col >= CELL_COLS) return 1;
    if (row < 0 || row >= CELL_ROWS) return 1;
    return (g_cell_solid[level][row] >> col) & 1u;
}

/* Return 1 if cell (col,row) of `level` is an exit/trigger cell. */
static int cc_cell_exit(int level, int col, int row) {
    if (level < 0 || level >= CELL_LEVELS) return 0;
    if (col < 0 || col >= CELL_COLS) return 0;
    if (row < 0 || row >= CELL_ROWS) return 0;
    return (g_cell_exit[level][row] >> col) & 1u;
}

